eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   FAQ_CATEGORIES: () => (/* binding */ FAQ_CATEGORIES),\n/* harmony export */   SUPPORT_FAQS: () => (/* binding */ SUPPORT_FAQS),\n/* harmony export */   getFaqAnswer: () => (/* binding */ getFaqAnswer),\n/* harmony export */   getSupportBotReply: () => (/* binding */ getSupportBotReply)\n/* harmony export */ });\n// ─── FAQ 데이터 구조 ──────────────────────────────────────────────────────────\n// ─── FAQ 데이터 (1차 분류 → 2차 분류 → Q&A) ──────────────────────────────────\nconst FAQ_CATEGORIES = [\n    {\n        category: \"\\uD83D\\uDCB0 수익 \\xb7 정산\",\n        subcategories: [\n            {\n                name: \"수익 구조\",\n                faqs: [\n                    {\n                        question: \"수익은 어떻게 발생하나요?\",\n                        keywords: [\n                            \"수익\",\n                            \"돈\",\n                            \"얼마\",\n                            \"수익 구조\"\n                        ],\n                        answer: \"바이브퍼니 수익은 ① 숏폼 영상 제작 납품, ② 캠페인 참여 완료, ③ 콘텐츠 배포 성과, ④ 추천인 수당 등 네 가지 경로로 발생합니다. 각 항목별 수익 현황은 마이페이지 → 수익 현황에서 확인하실 수 있어요.\"\n                    },\n                    {\n                        question: \"수익 지급 기준이 무엇인가요?\",\n                        keywords: [\n                            \"지급 기준\",\n                            \"확정\",\n                            \"수익 기준\"\n                        ],\n                        answer: \"캠페인 완료 후 광고주 검수를 통과하면 수익이 '확정' 상태로 변경됩니다. 확정된 수익만 출금 신청이 가능하며, 검수 중인 수익은 출금 대상에서 제외됩니다.\"\n                    },\n                    {\n                        question: \"수익에 세금(원천징수)이 부과되나요?\",\n                        keywords: [\n                            \"세금\",\n                            \"원천징수\",\n                            \"3.3\",\n                            \"부가세\"\n                        ],\n                        answer: \"개인 크리에이터의 경우 지급액의 3.3%(소득세 3% + 지방소득세 0.3%)가 원천징수됩니다. 사업자 크리에이터는 세금계산서 발행 방식으로 처리됩니다. 정확한 세무 사항은 세무사에게 문의하시길 권장드립니다.\"\n                    }\n                ]\n            },\n            {\n                name: \"정산 \\xb7 출금\",\n                faqs: [\n                    {\n                        question: \"정산은 언제 이루어지나요?\",\n                        keywords: [\n                            \"정산\",\n                            \"언제\",\n                            \"정산 주기\"\n                        ],\n                        answer: \"캠페인 광고주 검수 완료 후 수익이 확정되며, 매월 말일까지 신청된 출금 건은 익월 10영업일 이내에 처리됩니다.\"\n                    },\n                    {\n                        question: \"출금 신청은 어떻게 하나요?\",\n                        keywords: [\n                            \"출금\",\n                            \"신청\",\n                            \"인출\"\n                        ],\n                        answer: \"마이페이지 → 포인트 \\xb7 출금 → 출금 신청 버튼을 누르시면 됩니다. 최초 출금 시 계좌 정보와 신분증 확인이 필요합니다.\"\n                    },\n                    {\n                        question: \"최소 출금 금액이 있나요?\",\n                        keywords: [\n                            \"최소\",\n                            \"최소금액\",\n                            \"출금 조건\"\n                        ],\n                        answer: \"최소 출금 가능 금액은 10,000원입니다. 10,000원 미만의 잔액은 다음 수익과 합산 후 출금 신청하실 수 있습니다.\"\n                    },\n                    {\n                        question: \"출금 수수료가 있나요?\",\n                        keywords: [\n                            \"수수료\",\n                            \"출금 비용\",\n                            \"이체 수수료\"\n                        ],\n                        answer: \"현재 출금 수수료는 별도로 부과되지 않습니다. 단, 은행 이체 수수료는 건당 500원이 공제될 수 있으며, 차후 정책 변경 시 사전 공지합니다.\"\n                    }\n                ]\n            },\n            {\n                name: \"포인트\",\n                faqs: [\n                    {\n                        question: \"포인트와 수익금의 차이가 무엇인가요?\",\n                        keywords: [\n                            \"포인트\",\n                            \"수익금\",\n                            \"차이\"\n                        ],\n                        answer: \"포인트는 플랫폼 내 활동 보상(댓글, 공유 등)으로 적립되며 서비스 내 혜택에 사용됩니다. 수익금은 캠페인 \\xb7 영상 납품 등 실제 업무를 통해 발생하며 현금 출금이 가능합니다.\"\n                    },\n                    {\n                        question: \"포인트는 어떻게 사용하나요?\",\n                        keywords: [\n                            \"포인트 사용\",\n                            \"포인트 쓰기\"\n                        ],\n                        answer: \"적립된 포인트는 마이페이지 → 포인트 메뉴에서 확인하실 수 있으며, 향후 콘텐츠 구매\\xb7서비스 이용 할인 등에 활용될 예정입니다.\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        category: \"\\uD83D\\uDCE2 캠페인\",\n        subcategories: [\n            {\n                name: \"캠페인 신청\",\n                faqs: [\n                    {\n                        question: \"캠페인 참여 방법이 궁금해요\",\n                        keywords: [\n                            \"캠페인\",\n                            \"참여\",\n                            \"신청\"\n                        ],\n                        answer: \"마이페이지 → 캠페인 메뉴에서 모집 중인 캠페인을 확인하고 참여 신청을 진행하세요. 승인 여부와 제출 일정도 같은 화면에서 확인할 수 있습니다.\"\n                    },\n                    {\n                        question: \"캠페인 신청 자격 조건이 있나요?\",\n                        keywords: [\n                            \"자격\",\n                            \"조건\",\n                            \"신청 조건\",\n                            \"팔로워\"\n                        ],\n                        answer: \"캠페인마다 요구 자격이 다릅니다. 일부 캠페인은 최소 팔로워 수, 계정 활성화 기간, 콘텐츠 카테고리 등의 조건이 있을 수 있으니 각 캠페인 상세 페이지를 확인해 주세요.\"\n                    },\n                    {\n                        question: \"캠페인 신청을 취소할 수 있나요?\",\n                        keywords: [\n                            \"취소\",\n                            \"신청 취소\",\n                            \"캠페인 취소\"\n                        ],\n                        answer: \"캠페인 진행 상태에 따라 취소 가능 여부가 다릅니다. 광고주가 승인하기 전 단계에서는 취소 신청이 가능하며, 승인 후에는 관리자에게 별도 문의가 필요합니다.\"\n                    }\n                ]\n            },\n            {\n                name: \"영상 제출\",\n                faqs: [\n                    {\n                        question: \"영상은 어디에서 제출하나요?\",\n                        keywords: [\n                            \"영상 제출\",\n                            \"업로드\",\n                            \"등록\"\n                        ],\n                        answer: \"캠페인 상세 페이지 → '결과물 제출' 버튼을 통해 제출하시면 됩니다. 크리에이터 일반 영상은 마이페이지 → 영상 판매 메뉴에서 등록하세요.\"\n                    },\n                    {\n                        question: \"영상 제출 기한이 언제까지인가요?\",\n                        keywords: [\n                            \"기한\",\n                            \"마감\",\n                            \"제출 기한\",\n                            \"데드라인\"\n                        ],\n                        answer: \"캠페인별 제출 기한은 캠페인 상세 페이지에 명시되어 있습니다. 기한 내 제출하지 않으면 캠페인에서 제외될 수 있으니 반드시 확인해 주세요.\"\n                    },\n                    {\n                        question: \"영상 규격(해상도, 길이) 조건이 있나요?\",\n                        keywords: [\n                            \"해상도\",\n                            \"길이\",\n                            \"규격\",\n                            \"포맷\",\n                            \"mp4\"\n                        ],\n                        answer: \"기본 권장 규격은 9:16 세로형 숏폼, 1080\\xd71920px, 최대 60초입니다. 캠페인에 따라 별도 규격이 요구될 수 있으니 캠페인 안내 내용을 꼭 확인하세요.\"\n                    }\n                ]\n            },\n            {\n                name: \"캠페인 결과\",\n                faqs: [\n                    {\n                        question: \"캠페인 승인 결과는 어떻게 확인하나요?\",\n                        keywords: [\n                            \"승인\",\n                            \"결과\",\n                            \"합격\",\n                            \"캠페인 결과\"\n                        ],\n                        answer: \"캠페인 목록 → 신청한 캠페인 → 상태 항목에서 '검토 중', '승인', '반려' 등의 결과를 확인할 수 있습니다. 상태 변경 시 알림도 발송됩니다.\"\n                    },\n                    {\n                        question: \"캠페인이 반려(리젝)됐어요. 이유를 알 수 있나요?\",\n                        keywords: [\n                            \"반려\",\n                            \"리젝\",\n                            \"거절\",\n                            \"이유\"\n                        ],\n                        answer: \"캠페인 상세 페이지에서 반려 사유를 확인할 수 있습니다. 사유 확인 후 수정\\xb7재제출이 가능한 경우 해당 안내가 함께 표시됩니다.\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        category: \"\\uD83C\\uDFAC 크리에이터\",\n        subcategories: [\n            {\n                name: \"가입 \\xb7 인증\",\n                faqs: [\n                    {\n                        question: \"크리에이터로 가입하려면 어떻게 하나요?\",\n                        keywords: [\n                            \"크리에이터 가입\",\n                            \"크리에이터 등록\",\n                            \"가입 방법\"\n                        ],\n                        answer: \"회원가입 화면에서 '숏폼 크리에이터'를 선택하고 이메일 인증 후 가입을 완료하세요. 가입 후 마이페이지에서 SNS 계정을 연결하면 캠페인 참여가 가능합니다.\"\n                    },\n                    {\n                        question: \"크리에이터 인증 조건이 있나요?\",\n                        keywords: [\n                            \"인증 조건\",\n                            \"팔로워 기준\",\n                            \"크리에이터 기준\"\n                        ],\n                        answer: \"기본 가입은 팔로워 제한이 없지만, 일부 프리미엄 캠페인은 최소 팔로워 기준이 적용됩니다. 계정 연결 후 실제 활동 이력을 기반으로 캠페인 매칭이 이루어집니다.\"\n                    },\n                    {\n                        question: \"크리에이터 가입비가 있나요?\",\n                        keywords: [\n                            \"크리에이터 가입비\",\n                            \"등록비\"\n                        ],\n                        answer: \"크리에이터 가입은 무료입니다. 가입비 없이 이메일 인증만으로 서비스를 시작할 수 있습니다.\"\n                    }\n                ]\n            },\n            {\n                name: \"영상 \\xb7 콘텐츠\",\n                faqs: [\n                    {\n                        question: \"영상은 어디에 등록하나요?\",\n                        keywords: [\n                            \"영상 등록\",\n                            \"영상 올리기\",\n                            \"영상 판매\"\n                        ],\n                        answer: \"마이페이지 → 영상 판매 메뉴에서 영상을 등록할 수 있습니다. 제목, 카테고리, 가격, 미리보기를 설정하고 등록하면 광고주에게 노출됩니다.\"\n                    },\n                    {\n                        question: \"영상은 몇 개까지 등록 가능한가요?\",\n                        keywords: [\n                            \"영상 개수\",\n                            \"등록 개수\",\n                            \"업로드 한도\"\n                        ],\n                        answer: \"현재 크리에이터 등급에 따라 등록 가능한 영상 수가 달라집니다. 기본 등급은 최대 20개, 프리미엄 등급은 무제한 등록이 가능합니다.\"\n                    },\n                    {\n                        question: \"어떤 콘텐츠는 금지되나요?\",\n                        keywords: [\n                            \"금지\",\n                            \"제한\",\n                            \"금지 콘텐츠\",\n                            \"정책 위반\"\n                        ],\n                        answer: \"성인 콘텐츠, 정치적 편향 콘텐츠, 허위\\xb7과장 광고, 타인 저작권 침해 콘텐츠, 폭력\\xb7혐오 표현 등은 금지됩니다. 위반 시 콘텐츠 삭제 및 계정 제재가 적용될 수 있습니다.\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        category: \"\\uD83D\\uDCE3 광고주\",\n        subcategories: [\n            {\n                name: \"광고주 가입\",\n                faqs: [\n                    {\n                        question: \"광고주(실행사)로 가입하려면 어떻게 하나요?\",\n                        keywords: [\n                            \"실행사 가입\",\n                            \"광고주 가입\",\n                            \"실행사\"\n                        ],\n                        answer: \"회원가입 화면에서 '광고주' → '실행사'를 선택하고 이메일 인증 후 가입을 완료하세요. 실행사는 직접 캠페인을 집행하고 크리에이터를 모집합니다.\"\n                    },\n                    {\n                        question: \"광고주(대행사)로 가입하려면 어떻게 하나요?\",\n                        keywords: [\n                            \"대행사 가입\",\n                            \"대행사\"\n                        ],\n                        answer: \"회원가입 화면에서 '광고주' → '대행사'를 선택하세요. 대행사 가입 시 실행사의 추천인 코드를 입력하거나 '추천인 없음'을 선택하면 됩니다.\"\n                    },\n                    {\n                        question: \"광고주 가입비가 있나요?\",\n                        keywords: [\n                            \"광고주 가입비\",\n                            \"비용\"\n                        ],\n                        answer: \"광고주 가입 시 가입비 정책이 적용될 수 있습니다. 현재 정책은 설정 → 가입비 안내에서 확인하시거나 관리자에게 문의해 주세요.\"\n                    }\n                ]\n            },\n            {\n                name: \"캠페인 집행\",\n                faqs: [\n                    {\n                        question: \"광고 캠페인은 어떻게 만드나요?\",\n                        keywords: [\n                            \"캠페인 만들기\",\n                            \"캠페인 생성\",\n                            \"광고 집행\"\n                        ],\n                        answer: \"광고주 마이페이지 → 캠페인 → '새 캠페인 만들기'에서 캠페인 정보, 요구 조건, 예산, 모집 인원 등을 입력하고 등록하세요. 관리자 검토 후 크리에이터에게 노출됩니다.\"\n                    },\n                    {\n                        question: \"캠페인 예산은 어떻게 설정하나요?\",\n                        keywords: [\n                            \"예산\",\n                            \"캠페인 비용\",\n                            \"광고비\"\n                        ],\n                        answer: \"캠페인 생성 시 1인당 지급 금액과 모집 인원을 입력하면 총 예산이 자동 계산됩니다. 예산은 캠페인 승인 전 예치 방식으로 처리됩니다.\"\n                    },\n                    {\n                        question: \"캠페인 진행 상태는 어디서 확인하나요?\",\n                        keywords: [\n                            \"캠페인 상태\",\n                            \"진행 현황\",\n                            \"캠페인 확인\"\n                        ],\n                        answer: \"광고주 마이페이지 → 캠페인 목록에서 각 캠페인의 진행 상태(모집 중, 검수 중, 완료 등)와 참여 크리에이터 현황을 실시간으로 확인할 수 있습니다.\"\n                    }\n                ]\n            },\n            {\n                name: \"추천인 코드\",\n                faqs: [\n                    {\n                        question: \"추천인 코드는 무엇인가요?\",\n                        keywords: [\n                            \"추천인 코드\",\n                            \"추천 코드\"\n                        ],\n                        answer: \"추천인 코드는 회원마다 발급되는 고유 코드로, 타인이 이 코드로 가입하면 추천 수당이 적립됩니다. 내 계정 정보 페이지에서 확인할 수 있습니다.\"\n                    },\n                    {\n                        question: \"추천인 링크는 어떻게 공유하나요?\",\n                        keywords: [\n                            \"추천 링크\",\n                            \"공유\",\n                            \"링크 복사\"\n                        ],\n                        answer: \"광고주(실행사) 계정의 '내 계정 정보'에서 추천인 링크를 복사해 공유하세요. 이 링크로 가입하면 내 추천인 코드가 자동 적용됩니다.\"\n                    },\n                    {\n                        question: \"추천 수당은 어떻게 받나요?\",\n                        keywords: [\n                            \"추천 수당\",\n                            \"추천 보상\",\n                            \"추천인 혜택\"\n                        ],\n                        answer: \"추천받은 회원이 가입 후 첫 캠페인을 완료하는 등 설정된 조건을 충족하면 추천 수당이 자동 적립됩니다. 수당 내역은 마이페이지 → 추천 현황에서 확인할 수 있습니다.\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        category: \"\\uD83D\\uDC64 계정 \\xb7 가입\",\n        subcategories: [\n            {\n                name: \"회원가입\",\n                faqs: [\n                    {\n                        question: \"회원가입은 어떻게 하나요?\",\n                        keywords: [\n                            \"회원가입\",\n                            \"가입 방법\",\n                            \"등록\"\n                        ],\n                        answer: \"상단 메뉴 또는 로그인 화면에서 '회원가입'을 클릭하세요. 회원 유형(크리에이터 / 광고주) 선택 → 이메일 인증 → 정보 입력 → 가입 완료 순서로 진행됩니다.\"\n                    },\n                    {\n                        question: \"이메일 인증이 오지 않아요\",\n                        keywords: [\n                            \"이메일 인증\",\n                            \"인증 메일\",\n                            \"인증 코드 안 옴\"\n                        ],\n                        answer: \"스팸 메일함을 먼저 확인해 주세요. 그래도 수신되지 않는다면 '인증번호 재전송' 버튼을 눌러 다시 받으실 수 있습니다. 계속 오류가 발생하면 사용하시는 이메일 주소를 문의 창에 남겨 주세요.\"\n                    },\n                    {\n                        question: \"어떤 회원 유형을 선택해야 하나요?\",\n                        keywords: [\n                            \"회원 유형\",\n                            \"크리에이터 광고주\",\n                            \"유형 선택\"\n                        ],\n                        answer: \"숏폼 영상을 직접 제작\\xb7납품할 계획이라면 '크리에이터', 크리에이터에게 광고를 의뢰할 계획이라면 '광고주'를 선택하세요. 가입 후 유형 변경은 불가하니 신중하게 선택해 주세요.\"\n                    }\n                ]\n            },\n            {\n                name: \"로그인\",\n                faqs: [\n                    {\n                        question: \"비밀번호를 잊었어요\",\n                        keywords: [\n                            \"비밀번호 분실\",\n                            \"비밀번호 찾기\",\n                            \"비밀번호 잊어버림\"\n                        ],\n                        answer: \"현재 비밀번호 찾기 기능은 관리자 지원으로 처리됩니다. 가입 시 사용한 이메일 주소를 문의 창에 남겨 주시면 재설정 안내를 보내드립니다.\"\n                    },\n                    {\n                        question: \"로그인이 안 돼요\",\n                        keywords: [\n                            \"로그인 오류\",\n                            \"로그인 안됨\",\n                            \"로그인 실패\"\n                        ],\n                        answer: \"이메일과 비밀번호를 다시 확인해 주세요. 비밀번호는 대소문자를 구분합니다. 계속 문제가 발생하면 증상과 사용 중인 이메일을 남겨 주시면 관리자가 확인해 드립니다.\"\n                    },\n                    {\n                        question: \"소셜 로그인(카카오\\xb7네이버\\xb7구글)은 언제 지원되나요?\",\n                        keywords: [\n                            \"소셜 로그인\",\n                            \"카카오\",\n                            \"네이버\",\n                            \"구글\"\n                        ],\n                        answer: \"소셜 로그인은 현재 준비 중입니다. 서비스 안정화 후 순차적으로 제공할 예정이며, 지원 시작 시 공지사항을 통해 안내드립니다.\"\n                    }\n                ]\n            },\n            {\n                name: \"계정 관리\",\n                faqs: [\n                    {\n                        question: \"프로필 정보를 변경하려면 어떻게 하나요?\",\n                        keywords: [\n                            \"프로필 변경\",\n                            \"정보 수정\",\n                            \"이름 변경\"\n                        ],\n                        answer: \"마이페이지 → 내 계정 정보에서 이름, 연락처 등 기본 정보를 수정할 수 있습니다. 이메일 변경은 보안상 별도 관리자 인증이 필요합니다.\"\n                    },\n                    {\n                        question: \"회원 탈퇴는 어떻게 하나요?\",\n                        keywords: [\n                            \"탈퇴\",\n                            \"계정 삭제\",\n                            \"회원 탈퇴\"\n                        ],\n                        answer: \"탈퇴 전 미정산 수익이 없는지 확인해 주세요. 탈퇴를 원하시면 이 문의 창에 탈퇴 요청을 남겨 주시면 관리자가 처리해 드립니다. 탈퇴 후 데이터는 복구되지 않습니다.\"\n                    },\n                    {\n                        question: \"계정이 정지됐어요\",\n                        keywords: [\n                            \"계정 정지\",\n                            \"이용 정지\",\n                            \"제재\"\n                        ],\n                        answer: \"이용 약관 위반 또는 비정상 활동이 감지되면 계정이 일시 정지될 수 있습니다. 정지 사유는 등록된 이메일로 발송됩니다. 이의 제기를 원하시면 상황을 문의 창에 남겨 주세요.\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        category: \"\\uD83D\\uDEE0 서비스 \\xb7 기술\",\n        subcategories: [\n            {\n                name: \"서비스 안내\",\n                faqs: [\n                    {\n                        question: \"바이브퍼니는 어떤 서비스인가요?\",\n                        keywords: [\n                            \"바이브퍼니\",\n                            \"서비스 소개\",\n                            \"플랫폼\"\n                        ],\n                        answer: \"바이브퍼니는 숏폼 크리에이터와 광고주를 연결하는 B2B 숏폼 마케팅 플랫폼입니다. 크리에이터는 영상을 제작\\xb7납품하고 수익을 얻으며, 광고주는 원하는 크리에이터에게 캠페인을 의뢰합니다.\"\n                    },\n                    {\n                        question: \"모바일에서도 이용 가능한가요?\",\n                        keywords: [\n                            \"모바일\",\n                            \"앱\",\n                            \"스마트폰\"\n                        ],\n                        answer: \"네, 모바일 브라우저에서도 바이브퍼니를 이용할 수 있습니다. 별도 앱 설치 없이 크롬, 사파리 등 모바일 브라우저에서 접속하세요. 전용 앱은 추후 출시 예정입니다.\"\n                    },\n                    {\n                        question: \"고객센터 운영 시간이 언제인가요?\",\n                        keywords: [\n                            \"운영 시간\",\n                            \"고객센터\",\n                            \"상담 시간\"\n                        ],\n                        answer: \"관리자 실시간 상담은 평일 오전 10시 ~ 오후 6시에 운영됩니다. 운영 시간 외 문의는 챗봇이 응대하며, 다음 영업일 관리자가 순서대로 답변드립니다.\"\n                    }\n                ]\n            },\n            {\n                name: \"오류 \\xb7 버그\",\n                faqs: [\n                    {\n                        question: \"페이지가 안 열리거나 흰 화면만 나와요\",\n                        keywords: [\n                            \"페이지 오류\",\n                            \"안 열림\",\n                            \"흰 화면\",\n                            \"로딩\"\n                        ],\n                        answer: \"브라우저 캐시 삭제 후 새로고침(Ctrl+Shift+R / Cmd+Shift+R)을 시도해 주세요. 계속 문제가 발생하면 사용 중인 브라우저 종류와 버전, 오류 화면을 문의에 남겨 주세요.\"\n                    },\n                    {\n                        question: \"결제가 안 돼요\",\n                        keywords: [\n                            \"결제 오류\",\n                            \"결제 실패\",\n                            \"가입비 결제\"\n                        ],\n                        answer: \"카드사 또는 PG사 일시 오류일 수 있습니다. 잠시 후 다시 시도해 주세요. 동일 오류가 반복되면 오류 메시지와 결제 시도 시각을 문의 창에 남겨 주시면 확인해 드립니다.\"\n                    },\n                    {\n                        question: \"알림이 오지 않아요\",\n                        keywords: [\n                            \"알림\",\n                            \"푸시 알림\",\n                            \"알림 안 옴\"\n                        ],\n                        answer: \"브라우저 알림 허용 여부를 확인해 주세요. 브라우저 설정 → 알림 → 바이브퍼니 주소에서 '허용'으로 변경하시면 됩니다. 이메일 알림은 스팸 폴더도 확인해 주세요.\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        category: \"\\uD83D\\uDCCB 정책 \\xb7 규정\",\n        subcategories: [\n            {\n                name: \"이용 약관\",\n                faqs: [\n                    {\n                        question: \"이용 약관은 어디서 볼 수 있나요?\",\n                        keywords: [\n                            \"이용 약관\",\n                            \"약관\",\n                            \"규정\"\n                        ],\n                        answer: \"하단 푸터의 '이용약관' 링크에서 전문을 확인하실 수 있습니다. 가입 시 동의한 약관 내용도 마이페이지에서 다시 확인 가능합니다.\"\n                    },\n                    {\n                        question: \"개인정보는 어떻게 처리되나요?\",\n                        keywords: [\n                            \"개인정보\",\n                            \"정보 보호\",\n                            \"개인정보 처리\"\n                        ],\n                        answer: \"수집된 개인정보는 서비스 제공 목적 외에는 사용되지 않으며, 관련 법률에 따라 안전하게 보관됩니다. 자세한 내용은 하단 '개인정보처리방침'에서 확인하세요.\"\n                    }\n                ]\n            },\n            {\n                name: \"콘텐츠 \\xb7 제재\",\n                faqs: [\n                    {\n                        question: \"저작권 관련 규정이 있나요?\",\n                        keywords: [\n                            \"저작권\",\n                            \"copyright\",\n                            \"원저작자\"\n                        ],\n                        answer: \"제출하는 모든 영상\\xb7이미지의 저작권은 크리에이터 본인에게 있어야 합니다. 타인의 음원, 영상, 이미지를 무단 사용하면 콘텐츠 삭제 및 계정 제재 대상이 됩니다.\"\n                    },\n                    {\n                        question: \"신고\\xb7제재 기준이 어떻게 되나요?\",\n                        keywords: [\n                            \"신고\",\n                            \"제재 기준\",\n                            \"경고\"\n                        ],\n                        answer: \"1차 위반: 콘텐츠 삭제 + 경고, 2차 위반: 일시 정지(7일), 3차 이상 위반: 영구 제재입니다. 심각한 위반(사기, 성인물 등)은 즉시 영구 제재가 적용됩니다.\"\n                    }\n                ]\n            }\n        ]\n    }\n];\n// ─── 기존 코드 호환용 flat export ─────────────────────────────────────────────\nconst SUPPORT_FAQS = FAQ_CATEGORIES.flatMap((c)=>c.subcategories.flatMap((s)=>s.faqs));\nfunction getSupportBotReply(content) {\n    const normalized = content.replace(/\\s+/g, \"\").toLowerCase();\n    const matched = SUPPORT_FAQS.find((faq)=>faq.keywords.some((keyword)=>normalized.includes(keyword.replace(/\\s+/g, \"\").toLowerCase())));\n    if (matched) return matched.answer;\n    return \"문의가 정상적으로 접수되었습니다. 담당 관리자가 확인 후 이 대화창으로 답변드릴게요. 운영 시간에는 순서대로 빠르게 안내해 드립니다.\";\n}\n// ─── FAQ 질문으로 바로 답변 가져오기 ─────────────────────────────────────────\nfunction getFaqAnswer(question) {\n    const item = SUPPORT_FAQS.find((f)=>f.question === question);\n    return item?.answer ?? null;\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/lib/support.ts\n");

